import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Kontrast, fotoğrafın canlılığıdır. Açık ve koyu arasındaki fark büyüdükçe fotoğraf güçlenir.</p>\n<p>Doğru kontrast, fotoğrafı uyandırır. Yanlış kontrast ise görseli sertleştirir ya da düzleştirir.</p>\n<p>Bu kılavuz, kontrast kaydırıcısının nasıl çalıştığını, hızlı ön ayarları ve parlak alanları kesmeden güç eklemenin yollarını anlatıyor.</p>\n<h2 id=\"what-contrast-does\">Kontrast gerçekte ne yapar?</h2>\n<p>Kontrast, açık pikselleri açar ve koyu pikselleri koyulaştırır. Aradaki fark büyür.</p>\n<p>Kontrast artırmak, fotoğrafı canlı gösterir. Renkler doygun, kenarlar keskin görünür.</p>\n<p>Kontrast azaltmak, fotoğrafı yumuşatır. Sert ışık, yumuşak hâle gelir.</p>\n<h2 id=\"why-photos-look-flat\">Fotoğraflar neden düz görünür?</h2>\n<p>Sisli hava, fotoğrafı düzleştirir. Işık dağılır; açık ve koyu arasındaki fark küçülür.</p>\n<p>Bulutlu günlerde çekilen fotoğraflar düz olur. Gölge yoktur; derinlik kaybolur.</p>\n<p>Eski taramalar da düz olabilir. Zamanla solan fotoğraflar, kontrastını kaybeder.</p>\n<h2 id=\"slider-explained\">Kontrast kaydırıcısı, açıklanıyor</h2>\n<p>Kontrast kaydırıcısı -100 ile +100 arasında işler. Sıfır, fotoğrafın orijinal hâlidir.</p>\n<p>Araçta kontrastı küçük adımlarla ayarlayın; düz fotoğrafların çoğu +10 ile +20 arasında düzelir.</p>\n<p>Aşırı değerler, fotoğrafı bozar. +50'nin üzeri, parlak alanları beyazlatır ve gölgeleri karartır.</p>\n<h2 id=\"quick-presets\">Tek tıkla düzeltmeler için hızlı ön ayarlar</h2>\n<p>Araçtaki hızlı ön ayarlarla başlayın; hafif güç, orta güç ve yumuşat hazır seçenekler arasındadır.</p>\n<p>Ön ayarı seçtikten sonra kaydırıcıyla ayarlayın. Ön ayar, başlangıç noktasıdır.</p>\n<p>Kendi ön ayarınızı kaydedin. Sürekli aynı düzeltmeyi yapıyorsanız işiniz hızlanır.</p>\n<h2 id=\"compare-modes\">Karşılaştırma modları: önce, sonra ve bölünmüş</h2>\n<p>Karşılaştırma modu, orijinali ve düzenlenen hâli yan yana koyar. Farkı anında fark edersiniz.</p>\n<p>Bölünmüş görünüm, görselin yarısını orijinal gösterir. Kaydırıcıyı hareket ettirip farkı görün.</p>\n<p>Karşılaştırma, aşırıya kaçmayı önler. Farkı gördükçe ayarı durdurursunuz.</p>\n<h2 id=\"contrast-and-colour\">Kontrast ve renk: birbirini nasıl etkiler?</h2>\n<p>Kontrast artınca renkler doygun görünür. Kırmızı daha kırmızı, mavi daha mavi olur.</p>\n<p>Kontrast azalınca renkler solar. Yumuşak görünüm, pastel tonlar yaratır.</p>\n<p>Renk ve kontrastı birlikte ayarlayın. İkisi birbirini etkiler; dengeyi birlikte bulun.</p>\n<h2 id=\"contrast-for-portraits\">Portrelerde kontrast</h2>\n<p>Portrelerde kontrastı düşük tutun. Fazla kontrast, cildi sert gösterir.</p>\n<p>Kontrastı +5 ile +10 arasında tutun. Yüz, yumuşak kalmalıdır.</p>\n<p>Gözleri kontrol edin. Gözler, portrenin odak noktasıdır; karanlık kalmamalıdır.</p>\n<h2 id=\"contrast-for-landscapes\">Manzaralarda kontrast</h2>\n<p>Manzaralarda kontrastı +10 ile +20 arasında tutun. Sisli fotoğraf canlanır.</p>\n<p>Araçta kontrastı ayarlarken gökyüzünü izleyin; aşırı kontrast, bulutları tamamen beyazlatır.</p>\n<p>Ön planı kontrol edin. Gölgeler çok kararmamalıdır.</p>\n<h2 id=\"contrast-for-screenshots\">Ekran görüntüleri ve belgelerde kontrast</h2>\n<p>Ekran görüntülerinde kontrastı artırın. Yazılar, zeminden ayrılır.</p>\n<p>Belgelerde +10 ile +20 arası kullanın. Yazılar keskin kalmalıdır.</p>\n<p>Ekran görüntüleri PNG ister. Kayıpsız sıkıştırma, metni bulanıklaştırmaz.</p>\n<h2 id=\"negative-contrast\">Negatif kontrast: sert fotoğrafları yumuşatmak</h2>\n<p>Negatif kontrast, açık ve koyu arasındaki farkı azaltır. Sert ışık yumuşar.</p>\n<p>Araçta öğle güneşi portrelerinde negatif kontrast deneyin; gölgeler yumuşayıp yüz dengelenir.</p>\n<p>Negatif kontrastı -10 ile -20 arasında tutun. Fazlası, fotoğrafı sisli gösterir.</p>\n<h2 id=\"clipping-and-crushing\">Parlak alanlar nasıl kesilir, gölgeler nasıl ezilir?</h2>\n<p>Fazla kontrast, parlak alanları beyaza çevirir. Ayrıntı kaybolur; geri gelmez.</p>\n<p>Fazla kontrast, gölgeleri siyaha çevirir. Koyu ayrıntı kaybolur.</p>\n<p>Sınırı izleyin. Histogram, kesilen alanları gösterir; beyaz ve siyah yığılma olmamalıdır.</p>\n<h2 id=\"formats-and-export\">Formatlar ve dışa aktarma</h2>\n<p>Kontrastı ayarlanan fotoğraflar için JPG idealdir. Küçük dosya, her yerde açılır.</p>\n<p>Saydam görseller için PNG idealdir. JPG saydamlığı taşıyamaz.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Kontrast ve parlaklık doğru olmalıdır.</p>\n<h2 id=\"contrast-vs-brightness\">Kontrast mı parlaklık mı: hangisi önce?</h2>\n<p>Önce parlaklığı ayarlayın. Genel aydınlık doğru olmalıdır.</p>\n<p>Sonra kontrastı ayarlayın. Derinlik ve canlılık ekleyin.</p>\n<p>Sıralama önemlidir. Önce kontrast artırmak, koyu alanları daha da karartır.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden düzenlemek</h2>\n<p>Kontrast aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu, kişisel fotoğraflarda önemlidir. Aile ve müşteri görsellerini rahatça düzenleyebilirsiniz.</p>\n<p>Düzenleme bitince veriler yok olur. Fotoğraflarınız cihazınızdan çıkmaz.</p>\n<h2 id=\"common-mistakes\">Kontrast ayarlarken yaygın hatalar</h2>\n<p>En yaygın hata, aşırı kontrasttır. +50'nin üzeri, parlak alanları beyazlatır.</p>\n<p>Bir başka hata, karşılaştırmadan düzenlemektir. Orijinali görmeden ayar yapmak, aşırıya kaçar.</p>\n<p>Üçüncü hata, orijinali silmektir. Düzenlenen görsel ayrı dosyadır; orijinali koruyun.</p>\n<h2 id=\"contrast-workflow\">Temiz kontrast düzenlemeleri için bir akış</h2>\n<p>Önce fotoğrafın ne kadar düz olduğunu değerlendirin. Hafif düzse +10, çok düzse +20 kullanın.</p>\n<p>Ardından kaydırıcıyla ayarlayın. Karşılaştırma moduyla farkı izleyin.</p>\n<p>Son olarak parlaklığı kontrol edin. Kontrast tek başına yeterli olmayabilir.</p>\n<h2 id=\"contrast-for-black-white\">Siyah beyaz fotoğraflarda kontrast</h2>\n<p>Siyah beyazda kontrast, her şeydir. Renk yoktur; yalnızca açık ve koyu vardır.</p>\n<p>Kontrastı +15 ile +25 arasında tutun. Siyah beyaz, güçlü kontrast ister.</p>\n<p>Gölgeleri kontrol edin. Siyah alanlar, ayrıntıyı kaybetmemelidir.</p>\n<p>Özetle: az kontrast ekleyin, parlak alanları izleyin, önce parlaklığı ayarlayın. Adımlar için <a href=\"/tr/blog/gorsel-kontrasti-nasil-ayarlanir\">Görsel kontrastı nasıl ayarlanır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/parlaklik-vs-pozlama-vs-kontrast\">parlaklık, pozlama ve kontrast karşılaştırması</a> yardımcı olur. Parlaklık için <a href=\"/tr/gorsel-parlaklik-ayarla\">görsel parlaklık düzenleyici</a>, doygunluk için <a href=\"/tr/gorsel-doygunluk-ayarla\">görsel doygunluk düzenleyici</a> hazırdır; araç ise <a href=\"/tr/gorsel-kontrast-ayarla\">görsel kontrast düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Düz bir fotoğrafa ne kadar kontrast eklemeliyim?","answer":"Genellikle +10 ile +20 arası yeterlidir. Küçük adımlarla ayarlayın ve karşılaştırma moduyla farkı izleyin. +50'nin üzeri parlak alanları beyazlatır ve gölgeleri karartır."},{"question":"Fotoğrafım kontrast ekledikten sonra neden sert görünüyor?","answer":"Çünkü kontrastı fazla artırdınız; açık ve koyu arasındaki fark çok büyüdü. Kontrastı azaltın; portrelerde +5 ile +10 arası yeterlidir. Negatif kontrast, sert fotoğrafı yumuşatır."},{"question":"Kontrast çok koyu bir fotoğrafı düzeltebilir mi?","answer":"Hayır. Kontrast, koyu alanları daha da karartır; koyu fotoğrafı düzeltmez. Önce parlaklıkla açın, sonra kontrast ekleyin. Çok koyu fotoğrafta kaybolan ayrıntı geri gelmez."},{"question":"Portre için pozitif mi negatif mi kontrast kullanmalıyım?","answer":"Genellikle hafif pozitif kontrast; +5 ile +10 arası. Fazla kontrast cildi sert gösterir. Sert ışıkta çekilen portrelerde negatif kontrast kullanın; gölgeler yumuşar."},{"question":"Kontrastı artırmak renkleri de güçlendirir mi?","answer":"Evet. Kontrast artınca renkler doygun görünür; kırmızı daha kırmızı, mavi daha mavi olur. Kontrast azalınca renkler solar. Renk ve kontrastı birlikte ayarlayın."},{"question":"Kişisel bir fotoğrafın kontrastını tarayıcı aracında düzenlemek güvenli mi?","answer":"Evet. Araç tamamen tarayıcıda çalışır; fotoğraflarınız sunucuya yüklenmez. İş bitince tarayıcı verisi silinir. Özel fotoğrafları güvenle düzenleyebilirsiniz."}];
